package com.sami.app.sales.receipt;
import com.sami.app.accounting.publicapi.ReceivableSettlementPort; import com.sami.app.common.tenancy.TenantContext; import com.sami.app.common.exception.*; import lombok.RequiredArgsConstructor; import org.springframework.jdbc.core.JdbcTemplate; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.math.BigDecimal; import java.time.Instant; import java.util.*;
@Service @RequiredArgsConstructor public class SalesReceiptService { private final JdbcTemplate jdbc; private final TenantContext tenants; private final Optional<ReceivableSettlementPort> settlement;
 @Transactional public Map<String,Object> create(Long companyId,Long branchId,Long customerId,BigDecimal amount,String method,String reference,String key){Long t=tenants.requireTenantId(); if(key==null||key.isBlank())throw new ApiException(ErrorCode.VALIDATION_FAILED,"Idempotency key is required"); List<Map<String,Object>> old=jdbc.queryForList("select * from sales_receipts where tenant_id=? and idempotency_key=?",t,key); if(!old.isEmpty())return old.getFirst(); jdbc.update("insert into sales_receipts(tenant_id,company_id,branch_id,customer_id,receipt_number,payment_date,amount,payment_method,reference,idempotency_key) values(?,?,?,?,?,?,?,?,?,?)",t,companyId,branchId,customerId,"RCT-"+jdbc.queryForObject("select nextval('sales_receipt_number_seq')",Long.class),Instant.now(),amount,method,reference,key); return jdbc.queryForMap("select * from sales_receipts where tenant_id=? and idempotency_key=?",t,key); }
 @Transactional public Map<String,Object> confirm(Long id){Long t=tenants.requireTenantId(); if(settlement.isEmpty())throw new ApiException(ErrorCode.OPERATION_NOT_ALLOWED,"Accounting settlement provider is unavailable"); Map<String,Object> r=jdbc.queryForMap("select * from sales_receipts where tenant_id=? and id=? for update",t,id); if("CONFIRMED".equals(r.get("status")))return r; settlement.get().settle(new ReceivableSettlementPort.ReceiptSettlementCommand(t,(Long)r.get("company_id"),(Long)r.get("branch_id"),(Long)r.get("customer_id"),null,(BigDecimal)r.get("amount"),"IRR",Instant.now(),"SALES-RECEIPT-"+t+"-"+id)); jdbc.update("update sales_receipts set status='CONFIRMED',confirmed_at=now(),version=version+1 where tenant_id=? and id=?",t,id); return jdbc.queryForMap("select * from sales_receipts where tenant_id=? and id=?",t,id); }
}
